import { useState } from "react";
import Button from "../common/Button/Button";
import styles from "./AuthCard.module.scss";
import TextInput from "../common/Inputs/TextInput/TextInput";
import TextButton from "../common/TextButton/TextButton";

const AuthCard = () => {
  const [btnType, setBtnType] = useState("login");
   const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsLoading(true);

    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 2000));

      if (authType === "login") {
        console.log("Login:", { email: formData.email, password: formData.password });
      } else {
        console.log("Signup:", formData);
      }

      // Handle success (redirect, show message, etc.)
    } catch (error) {
      console.error("Auth error:", error);
      // Handle error
    } finally {
      setIsLoading(false);
    }
  };
  return (
    <div className={styles.authContainer}>
        {/* Auth Type Switch */}
      <div className={styles.authSwitchButtonBox}>
        <Button
          className={`${styles.btn} ${
            btnType === "login" ? styles.atciveBtn : ""
          }`}
          text={"Login"}
          onClick={() => setBtnType("login")}
        />
        <Button
          className={`${styles.btn} ${
            btnType === "signup" ? styles.atciveBtn : ""
          }`}
          text={"Signup"}
          onClick={() => setBtnType("signup")}
        />
      </div>

      <form onSubmit={handleSubmit} className={styles.authForm}></form>
      {btnType === "login" ? (
        <>
          <div className={styles.inputsContainer}>
            <TextInput label="Email Address" placeholder="you@example.com" />
            <TextInput
              label="Password"
              type="password"
              placeholder="********"
            />
          </div>
          <div className={styles.TextButtonContainer}>
            <TextButton
              href="/forgot-password"
              className={styles.TextButton}
              variant="primary"
              size="sm"
            >
              Forgot Password?
            </TextButton>
          </div>

          <Button
            className={styles.signBtn}
            text={"Login"}
            onClick={() => {}}
          />
        </>
      ) : (
        <>
          <div className={styles.inputsContainer}>
            <TextInput
              label="Full Name"
              placeholder="Omran Abandeh"
              errorMessage=""
            />
            <TextInput label="Email Address" placeholder="you@example.com" />
            <TextInput
              label="Password"
              type="password"
              placeholder="********"
            />
            <TextInput
              label="Confirm Password"
              type="password"
              placeholder="********"
            />
          </div>
          <div className={styles.TextButtonContainer}>
            <TextButton
              href="/forgot-password"
              className={styles.TextButton}
              variant="primary"
              size="sm"
            >
              Forgot Password?
            </TextButton>
          </div>

          <Button
            className={styles.signBtn}
            text={"Login"}
            onClick={() => {}}
          />
        </>
      )}
    </div>
  );
};

export default AuthCard;
